@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (error is not null)
{
    <div class="alert alert-danger">
        <strong>Error:</strong> @error
        <button class="btn btn-sm btn-outline-danger ms-2" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStatsBar Total="tasks.Count"
                   ToDo="todoTasks.Count"
                   InProgress="inProgressTasks.Count"
                   DoneCount="doneTasks.Count"
                   Overdue="tasks.Count(t => t.DueDate < DateTime.Today)" />

    <BoardSearchBar @bind-SearchTerm="searchTerm" />

    <div class="row g-3">
        <KanbanColumn ColumnName="To Do"
                      Tasks="FilteredTasks(todoTasks)"
                      MoveRightStatus="In Progress"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="request => HandleAddTask(request, \"To Do\")" />

        <KanbanColumn ColumnName="In Progress"
                      Tasks="FilteredTasks(inProgressTasks)"
                      MoveLeftStatus="To Do"
                      MoveRightStatus="Done"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="request => HandleAddTask(request, \"In Progress\")" />

        <KanbanColumn ColumnName="Done"
                      Tasks="FilteredTasks(doneTasks)"
                      MoveLeftStatus="In Progress"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="request => HandleAddTask(request, \"Done\")" />
    </div>
}

@code {
    private List<TaskItem> tasks = new();
    private bool loading = true;
    private string? error;
    private string searchTerm = "";

    private List<TaskItem> todoTasks => tasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> inProgressTasks => tasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> doneTasks => tasks.Where(t => t.Status == "Done").ToList();

    private List<TaskItem> FilteredTasks(List<TaskItem> source)
    {
        if (string.IsNullOrWhiteSpace(searchTerm))
            return source;
        return source.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        loading = true;
        error = null;
        try
        {
            tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            error = ex.Message;
        }
        finally
        {
            loading = false;
        }
    }

    private async Task HandleMoveTask((int TaskId, string NewStatus) move)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(move.TaskId, move.NewStatus);
            var task = tasks.First(t => t.Id == move.TaskId);
            var index = tasks.IndexOf(task);
            tasks[index] = task with { Status = move.NewStatus };
        }
        catch (Exception ex)
        {
            error = ex.Message;
        }
    }

    private async Task HandleAddTask(AddTaskForm.AddTaskRequest request, string status)
    {
        var created = await TaskService.CreateTaskAsync(request.Title, request.Assignee, request.Priority, request.DueDate);
        tasks.Add(created with { Status = status });
    }
}

